// 힙 메모리 관리 (Heap Memory Management)
// Phase 5: 런타임

use crate::value::Value;

/// 힙 메모리 관리자
#[derive(Debug, Clone)]
pub struct Heap {
    /// 메모리 저장소
    memory: Vec<Value>,
    /// 해제된 블록 (재사용 리스트)
    free_list: Vec<usize>,
}

impl Heap {
    /// 새 힙 생성
    pub fn new() -> Self {
        Heap {
            memory: Vec::new(),
            free_list: Vec::new(),
        }
    }

    /// 메모리 할당
    /// 새로운 값을 힙에 할당하고 주소를 반환합니다
    pub fn allocate(&mut self, value: Value) -> usize {
        // 해제된 블록이 있으면 재사용
        if let Some(addr) = self.free_list.pop() {
            self.memory[addr] = value;
            addr
        } else {
            // 새 메모리 할당
            let addr = self.memory.len();
            self.memory.push(value);
            addr
        }
    }

    /// 메모리 해제
    /// 주소의 값을 제거하고 블록을 해제 목록에 추가합니다
    pub fn deallocate(&mut self, addr: usize) -> Result<(), String> {
        if addr >= self.memory.len() {
            return Err(format!("Invalid address: {}", addr));
        }
        self.free_list.push(addr);
        Ok(())
    }

    /// 메모리에서 값 읽기
    pub fn get(&self, addr: usize) -> Result<&Value, String> {
        if addr >= self.memory.len() {
            return Err(format!("Invalid address: {}", addr));
        }
        Ok(&self.memory[addr])
    }

    /// 메모리에 값 쓰기
    pub fn set(&mut self, addr: usize, value: Value) -> Result<(), String> {
        if addr >= self.memory.len() {
            return Err(format!("Invalid address: {}", addr));
        }
        self.memory[addr] = value;
        Ok(())
    }

    /// 힙 크기 (할당된 블록 수)
    pub fn size(&self) -> usize {
        self.memory.len()
    }

    /// 해제된 블록 수
    pub fn free_count(&self) -> usize {
        self.free_list.len()
    }

    /// 힙 초기화
    pub fn clear(&mut self) {
        self.memory.clear();
        self.free_list.clear();
    }

    /// 전체 메모리 정리
    pub fn gc(&mut self) {
        // 간단한 GC: 해제된 블록을 실제로 제거하지 않음 (마킹만 함)
        // 더 정교한 GC는 나중에 구현
    }
}

impl Default for Heap {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_heap_allocate() {
        let mut heap = Heap::new();
        let addr = heap.allocate(Value::Integer(42));
        assert_eq!(addr, 0);
        assert_eq!(heap.size(), 1);
    }

    #[test]
    fn test_heap_get() {
        let mut heap = Heap::new();
        let addr = heap.allocate(Value::Integer(42));
        let val = heap.get(addr).unwrap();
        assert!(matches!(val, Value::Integer(42)));
    }

    #[test]
    fn test_heap_set() {
        let mut heap = Heap::new();
        let addr = heap.allocate(Value::Integer(42));
        heap.set(addr, Value::Integer(100)).unwrap();
        let val = heap.get(addr).unwrap();
        assert!(matches!(val, Value::Integer(100)));
    }

    #[test]
    fn test_heap_deallocate() {
        let mut heap = Heap::new();
        let addr = heap.allocate(Value::Integer(42));
        assert_eq!(heap.free_count(), 0);
        heap.deallocate(addr).unwrap();
        assert_eq!(heap.free_count(), 1);
    }

    #[test]
    fn test_heap_deallocate_invalid() {
        let mut heap = Heap::new();
        let result = heap.deallocate(999);
        assert!(result.is_err());
    }

    #[test]
    fn test_heap_allocate_reuse() {
        let mut heap = Heap::new();
        let addr1 = heap.allocate(Value::Integer(42));
        let addr2 = heap.allocate(Value::Integer(100));
        assert_eq!(addr1, 0);
        assert_eq!(addr2, 1);

        heap.deallocate(addr1).unwrap();
        let addr3 = heap.allocate(Value::String("hello".to_string()));
        assert_eq!(addr3, 0); // 재사용된 주소
    }

    #[test]
    fn test_heap_multiple_allocations() {
        let mut heap = Heap::new();
        let addr1 = heap.allocate(Value::Integer(1));
        let addr2 = heap.allocate(Value::Integer(2));
        let addr3 = heap.allocate(Value::Integer(3));

        assert_eq!(addr1, 0);
        assert_eq!(addr2, 1);
        assert_eq!(addr3, 2);
        assert_eq!(heap.size(), 3);
    }

    #[test]
    fn test_heap_string_allocation() {
        let mut heap = Heap::new();
        let addr = heap.allocate(Value::String("hello world".to_string()));
        let val = heap.get(addr).unwrap();
        match val {
            Value::String(s) => assert_eq!(s, "hello world"),
            _ => panic!("Expected string"),
        }
    }

    #[test]
    fn test_heap_clear() {
        let mut heap = Heap::new();
        heap.allocate(Value::Integer(42));
        heap.allocate(Value::Integer(100));
        assert_eq!(heap.size(), 2);

        heap.clear();
        assert_eq!(heap.size(), 0);
        assert_eq!(heap.free_count(), 0);
    }

    #[test]
    fn test_heap_get_invalid() {
        let heap = Heap::new();
        let result = heap.get(999);
        assert!(result.is_err());
    }
}

