    pub fn pop_frame(&mut self) -> Result<StackFrame, String> {
        if self.frames.len() <= 1 {
            return Err("Cannot pop global frame".to_string());
        }
        self.frames.pop().ok_or_else(|| "Stack underflow".to_string())
    }

    /// 현재 프레임 (가장 위의 프레임)
    pub fn current_frame(&self) -> Option<&StackFrame> {
        self.frames.last()
    }

    /// 현재 프레임 (가변)
    pub fn current_frame_mut(&mut self) -> Option<&mut StackFrame> {
        self.frames.last_mut()
    }

    /// 현재 프레임에 변수 저장
    pub fn set_var(&mut self, name: String, value: Value) -> Result<(), String> {
        if let Some(frame) = self.frames.last_mut() {
            frame.set_var(name, value);
            Ok(())
        } else {
            Err("No active frame".to_string())
        }
    }

    /// 변수 읽기 (현재 프레임에서 시작, 글로벌까지 탐색)
    pub fn get_var(&self, name: &str) -> Option<Value> {
        // 현재 프레임부터 글로벌 프레임까지 역순 탐색
        for i in (0..self.frames.len()).rev() {
            if let Some(value) = self.frames[i].get_var(name) {
                return Some(value);
            }
        }
        None
    }

    /// 변수가 존재하는지 확인
    pub fn has_var(&self, name: &str) -> bool {
        self.frames.iter().any(|f| f.has_var(name))
    }

    /// 스택 깊이 (프레임 개수)
    pub fn depth(&self) -> usize {
        self.frames.len()
    }

    /// 스택 비우기
    pub fn clear(&mut self) {
        self.frames.clear();
        self.frames.push(StackFrame::new("global".to_string(), 0));
    }

    /// 글로벌 변수 저장 (글로벌 프레임에만)
    pub fn set_global_var(&mut self, name: String, value: Value) -> Result<(), String> {
        if let Some(frame) = self.frames.first_mut() {
            frame.set_var(name, value);
            Ok(())
        } else {
            Err("No global frame".to_string())
        }
    }

    /// 글로벌 변수 읽기
    pub fn get_global_var(&self, name: &str) -> Option<Value> {
        if let Some(frame) = self.frames.first() {
            frame.get_var(name)
        } else {
            None
        }
    }
}

impl Default for Stack {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_stack_create() {
        let stack = Stack::new();
        assert_eq!(stack.depth(), 1); // 글로벌 프레임
    }

    #[test]
    fn test_stack_push_frame() {
        let mut stack = Stack::new();
        let frame = StackFrame::new("test_func".to_string(), 100);
        stack.push_frame(frame);
        assert_eq!(stack.depth(), 2);
    }

    #[test]
    fn test_stack_pop_frame() {
        let mut stack = Stack::new();
        let frame = StackFrame::new("test_func".to_string(), 100);
        stack.push_frame(frame);
        assert_eq!(stack.depth(), 2);

        let popped = stack.pop_frame().unwrap();
        assert_eq!(popped.function_name, "test_func");
        assert_eq!(stack.depth(), 1);
    }

    #[test]
    fn test_stack_pop_global_frame_error() {
        let mut stack = Stack::new();
        let result = stack.pop_frame();
        // 글로벌 프레임만 남을 때는 팝할 수 없음
        assert!(result.is_err());
    }

    #[test]
    fn test_stack_set_var() {
        let mut stack = Stack::new();
        let result = stack.set_var("x".to_string(), Value::Integer(42));
        assert!(result.is_ok());
    }

    #[test]
    fn test_stack_get_var() {
        let mut stack = Stack::new();
        stack.set_var("x".to_string(), Value::Integer(42)).unwrap();
        let val = stack.get_var("x");
        assert!(matches!(val, Some(Value::Integer(42))));
    }

    #[test]
    fn test_stack_variable_scope() {
        let mut stack = Stack::new();
        // 글로벌 변수 설정
        stack.set_var("x".to_string(), Value::Integer(10)).unwrap();

        // 함수 프레임 추가
        let mut frame = StackFrame::new("func".to_string(), 100);
        frame.set_var("x".to_string(), Value::Integer(20));
        stack.push_frame(frame);

        // 현재 프레임의 x는 20
        assert_eq!(stack.get_var("x"), Some(Value::Integer(20)));

        // 프레임 팝
        stack.pop_frame().unwrap();

        // 글로벌의 x는 10
        assert_eq!(stack.get_var("x"), Some(Value::Integer(10)));
    }

    #[test]
    fn test_stack_multiple_frames() {
        let mut stack = Stack::new();
        assert_eq!(stack.depth(), 1);

        let f1 = StackFrame::new("func1".to_string(), 100);
        let f2 = StackFrame::new("func2".to_string(), 200);
        let f3 = StackFrame::new("func3".to_string(), 300);

        stack.push_frame(f1);
        assert_eq!(stack.depth(), 2);

        stack.push_frame(f2);
        assert_eq!(stack.depth(), 3);

        stack.push_frame(f3);
        assert_eq!(stack.depth(), 4);

        stack.pop_frame().unwrap();
        assert_eq!(stack.depth(), 3);
    }

    #[test]
    fn test_stack_global_var() {
        let mut stack = Stack::new();
        stack.set_global_var("global_x".to_string(), Value::Integer(100)).unwrap();

        // 글로벌 변수는 어디서든 접근 가능
        assert_eq!(stack.get_global_var("global_x"), Some(Value::Integer(100)));
        assert_eq!(stack.get_var("global_x"), Some(Value::Integer(100)));
    }

    #[test]
    fn test_stack_frame_var_count() {
        let mut frame = StackFrame::new("func".to_string(), 100);
        assert_eq!(frame.var_count(), 0);

        frame.set_var("x".to_string(), Value::Integer(42));
        assert_eq!(frame.var_count(), 1);

        frame.set_var("y".to_string(), Value::String("hello".to_string()));
        assert_eq!(frame.var_count(), 2);
    }

    #[test]
    fn test_stack_clear() {
        let mut stack = Stack::new();
        let frame = StackFrame::new("func".to_string(), 100);
        stack.push_frame(frame);
        assert_eq!(stack.depth(), 2);

        stack.clear();
        assert_eq!(stack.depth(), 1); // 글로벌 프레임만
    }
}

