// Phase 5 Stage 1: 메모리 및 스택 관리 테스트
// Memory Management & Call Stack Testing

use fv_lang::{Heap, Stack, StackFrame, Value};

#[test]
fn test_heap_basic_allocation() {
    let mut heap = Heap::new();

    // 정수 할당
    let int_addr = heap.allocate(Value::Integer(42));
    assert_eq!(int_addr, 0);

    // 문자열 할당
    let str_addr = heap.allocate(Value::String("hello".to_string()));
    assert_eq!(str_addr, 1);

    // 검증
    let int_val = heap.get(int_addr).unwrap();
    assert!(matches!(int_val, Value::Integer(42)));

    let str_val = heap.get(str_addr).unwrap();
    assert!(matches!(str_val, Value::String(ref s) if s == "hello"));
}

#[test]
fn test_heap_modification() {
    let mut heap = Heap::new();

    let addr = heap.allocate(Value::Integer(10));

    // 값 변경
    heap.set(addr, Value::Integer(20)).unwrap();

    let val = heap.get(addr).unwrap();
    assert!(matches!(val, Value::Integer(20)));
}

#[test]
fn test_heap_deallocation_and_reuse() {
    let mut heap = Heap::new();

    // 3개 할당
    let addr1 = heap.allocate(Value::Integer(1));
    let addr2 = heap.allocate(Value::Integer(2));
    let addr3 = heap.allocate(Value::Integer(3));

    assert_eq!(addr1, 0);
    assert_eq!(addr2, 1);
    assert_eq!(addr3, 2);

    // 첫 번째 해제
    heap.deallocate(addr1).unwrap();

    // 새 할당 → 재사용된 주소
    let addr4 = heap.allocate(Value::String("reused".to_string()));
    assert_eq!(addr4, 0); // addr1의 주소 재사용
}

#[test]
fn test_stack_basic_operations() {
    let mut stack = Stack::new();

    // 초기 상태 확인
    assert_eq!(stack.depth(), 1); // 글로벌 프레임

    // 변수 저장
    stack.set_var("x".to_string(), Value::Integer(10)).unwrap();

    // 변수 읽기
    let val = stack.get_var("x");
    assert_eq!(val, Some(Value::Integer(10)));
}

#[test]
fn test_stack_frame_push_pop() {
    let mut stack = Stack::new();
    assert_eq!(stack.depth(), 1);

    // 함수 호출 → 프레임 추가
    let frame = StackFrame::new("add".to_string(), 100);
    stack.push_frame(frame);
    assert_eq!(stack.depth(), 2);

    // 함수 내부에서 변수 저장
    stack.set_var("a".to_string(), Value::Integer(5)).unwrap();
    stack.set_var("b".to_string(), Value::Integer(7)).unwrap();

    // 함수 반환 → 프레임 제거
    let popped = stack.pop_frame().unwrap();
    assert_eq!(popped.function_name, "add");
    assert_eq!(stack.depth(), 1);

    // 이제 a, b는 접근 불가능
    assert_eq!(stack.get_var("a"), None);
    assert_eq!(stack.get_var("b"), None);
}

#[test]
fn test_stack_variable_shadowing() {
    let mut stack = Stack::new();

    // 글로벌에서 x = 100
    stack.set_var("x".to_string(), Value::Integer(100)).unwrap();
    assert_eq!(stack.get_var("x"), Some(Value::Integer(100)));

    // 함수 호출 → 새 프레임
    let frame = StackFrame::new("func".to_string(), 50);
    stack.push_frame(frame);

    // 함수에서 x = 200 (섀도잉)
    stack.set_var("x".to_string(), Value::Integer(200)).unwrap();
    assert_eq!(stack.get_var("x"), Some(Value::Integer(200)));

    // 함수 반환
    stack.pop_frame().unwrap();

    // 글로벌의 x 복원
    assert_eq!(stack.get_var("x"), Some(Value::Integer(100)));
}

#[test]
fn test_stack_nested_function_calls() {
    let mut stack = Stack::new();

    // 글로벌 변수
    stack.set_global_var("global_x".to_string(), Value::Integer(1)).unwrap();

    // 첫 번째 함수 호출
    let f1 = StackFrame::new("f1".to_string(), 100);
    stack.push_frame(f1);
    stack.set_var("local_x".to_string(), Value::Integer(10)).unwrap();
    assert_eq!(stack.depth(), 2);

    // 두 번째 함수 호출 (중첩)
    let f2 = StackFrame::new("f2".to_string(), 200);
    stack.push_frame(f2);
    stack.set_var("local_y".to_string(), Value::String("inner".to_string())).unwrap();
    assert_eq!(stack.depth(), 3);

    // 글로벌 변수 여전히 접근 가능
    assert_eq!(stack.get_var("global_x"), Some(Value::Integer(1)));

    // f2 반환
    stack.pop_frame().unwrap();
    assert_eq!(stack.depth(), 2);
    assert_eq!(stack.get_var("local_y"), None); // f2의 local_y 제거됨
    assert_eq!(stack.get_var("local_x"), Some(Value::Integer(10))); // f1의 local_x는 여전히 있음

    // f1 반환
    stack.pop_frame().unwrap();
    assert_eq!(stack.depth(), 1);
}

#[test]
fn test_value_type_conversions() {
    // Integer → Float
    let int_val = Value::Integer(42);
    let float_val = int_val.to_float();
    assert_eq!(float_val, Some(42.0));

    // Float → Integer
    let float_val = Value::Float(3.14);
    let int_val = float_val.to_integer();
    assert_eq!(int_val, Some(3));

    // String → Boolean (non-empty)
    let str_val = Value::String("hello".to_string());
    assert!(str_val.to_bool());

    // Empty String → Boolean
    let empty_str = Value::String("".to_string());
    assert!(!empty_str.to_bool());
}

#[test]
fn test_value_array_operations() {
    let mut array = Value::Array(vec![
        Value::Integer(1),
        Value::Integer(2),
        Value::Integer(3),
    ]);

    // 길이 확인
    assert_eq!(array.len(), Some(3));

    // 인덱싱
    assert_eq!(array.get_index(0), Some(Value::Integer(1)));
    assert_eq!(array.get_index(2), Some(Value::Integer(3)));
    assert_eq!(array.get_index(10), None); // Out of bounds

    // 요소 추가
    array.push(Value::Integer(4)).unwrap();
    assert_eq!(array.len(), Some(4));
    assert_eq!(array.get_index(3), Some(Value::Integer(4)));
}

#[test]
fn test_memory_and_stack_integration() {
    let mut heap = Heap::new();
    let mut stack = Stack::new();

    // 글로벌 변수로 힙 할당
    let addr1 = heap.allocate(Value::Integer(100));
    stack.set_global_var("heap_ref".to_string(), Value::Integer(addr1 as i64)).unwrap();

    // 함수 호출
    let mut frame = StackFrame::new("func".to_string(), 50);
    frame.set_var("local_addr".to_string(), Value::Integer(addr1 as i64));
    stack.push_frame(frame);

    // 힙의 값 수정
    heap.set(addr1, Value::Integer(200)).unwrap();

    // 함수 내부에서도 접근 가능
    let ref_val = stack.get_var("local_addr");
    if let Some(Value::Integer(addr)) = ref_val {
        let heap_val = heap.get(addr as usize).unwrap();
        assert!(matches!(heap_val, Value::Integer(200)));
    }

    stack.pop_frame().unwrap();
}

#[test]
fn test_heap_array_allocation() {
    let mut heap = Heap::new();

    let array = Value::Array(vec![
        Value::Integer(10),
        Value::Integer(20),
        Value::Integer(30),
    ]);

    let addr = heap.allocate(array);

    let retrieved = heap.get(addr).unwrap();
    assert!(matches!(retrieved, Value::Array(_)));

    if let Value::Array(arr) = retrieved {
        assert_eq!(arr.len(), 3);
    }
}

#[test]
fn test_stack_multiple_variables() {
    let mut stack = Stack::new();

    // 여러 변수 저장
    stack.set_var("x".to_string(), Value::Integer(10)).unwrap();
