    stack.set_var("z".to_string(), Value::Boolean(true)).unwrap();
    stack.set_var("arr".to_string(), Value::Array(vec![
        Value::Integer(1),
        Value::Integer(2),
    ])).unwrap();

    // 모두 접근 가능
    assert_eq!(stack.get_var("x"), Some(Value::Integer(10)));
    assert!(matches!(stack.get_var("y"), Some(Value::String(ref s)) if s == "hello"));
    assert_eq!(stack.get_var("z"), Some(Value::Boolean(true)));
    assert!(matches!(stack.get_var("arr"), Some(Value::Array(_))));
}

