// 런타임 엔진 (Runtime Engine)
// Phase 5 Stage 2: 런타임 실행

use crate::value::Value;
use crate::heap::Heap;
use crate::stack::Stack;
use crate::ir::IRNode;
use std::collections::HashMap;

/// 런타임 에러
#[derive(Debug, Clone, PartialEq)]
pub enum RuntimeError {
    TypeMismatch { expected: String, got: String },
    UndefinedVariable(String),
    UndefinedFunction(String),
    DivisionByZero,
    IndexOutOfBounds { index: i64, length: usize },
    StackOverflow,
    InvalidOperation(String),
    StackUnderflow,
    EmptyReturn,
}

impl std::fmt::Display for RuntimeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            RuntimeError::TypeMismatch { expected, got } => {
                write!(f, "Type mismatch: expected {}, got {}", expected, got)
            }
            RuntimeError::UndefinedVariable(var) => write!(f, "Undefined variable: {}", var),
            RuntimeError::UndefinedFunction(func) => write!(f, "Undefined function: {}", func),
            RuntimeError::DivisionByZero => write!(f, "Division by zero"),
            RuntimeError::IndexOutOfBounds { index, length } => {
                write!(f, "Index out of bounds: {} (length: {})", index, length)
            }
            RuntimeError::StackOverflow => write!(f, "Stack overflow"),
            RuntimeError::InvalidOperation(op) => write!(f, "Invalid operation: {}", op),
            RuntimeError::StackUnderflow => write!(f, "Stack underflow"),
            RuntimeError::EmptyReturn => write!(f, "Empty return value"),
        }
    }
}

impl std::error::Error for RuntimeError {}

/// 함수 정보
#[derive(Debug, Clone)]
pub struct FunctionDef {
    pub name: String,
    pub params: Vec<String>,
    pub body: Vec<IRNode>,
}

/// 런타임 환경
#[derive(Debug, Clone)]
pub struct Runtime {
    /// 힙 메모리
    heap: Heap,
    /// 호출 스택
    stack: Stack,
    /// 프로그램 카운터
    pc: usize,
    /// 정의된 함수들
    functions: HashMap<String, FunctionDef>,
    /// 반환값 저장소
    return_value: Option<Value>,
}

impl Runtime {
    /// 새 런타임 생성
    pub fn new() -> Self {
        Runtime {
            heap: Heap::new(),
            stack: Stack::new(),
            pc: 0,
            functions: HashMap::new(),
            return_value: None,
        }
    }

    /// 프로그램 실행
    pub fn execute(&mut self, nodes: &[IRNode]) -> Result<Value, RuntimeError> {
        self.pc = 0;
        self.return_value = None;

        // 최대 스택 깊이 확인 (오버플로우 방지)
        const MAX_STACK_DEPTH: usize = 1000;

        for node in nodes {
            if self.stack.depth() > MAX_STACK_DEPTH {
                return Err(RuntimeError::StackOverflow);
            }

            self.eval_node(node)?;

            // 반환값이 설정되면 중단
            if self.return_value.is_some() {
                break;
            }
        }

        // 반환값이 있으면 반환, 없으면 None
        Ok(self.return_value.take().unwrap_or(Value::None))
    }

    /// 노드 평가
    pub fn eval_node(&mut self, node: &IRNode) -> Result<(), RuntimeError> {
        match node {
            IRNode::Literal { value } => {
                self.return_value = Some(value.clone());
                Ok(())
            }
            IRNode::Variable { name } => {
                let val = self
                    .stack
                    .get_var(name)
                    .ok_or_else(|| RuntimeError::UndefinedVariable(name.clone()))?;
                self.return_value = Some(val);
                Ok(())
            }
            IRNode::Assign { name, value } => {
                self.eval_node(value)?;
                let val = self.return_value.take().ok_or(RuntimeError::EmptyReturn)?;
                self.stack.set_var(name.clone(), val)?;
                self.return_value = Some(Value::None);
                Ok(())
            }
            IRNode::BinaryOp { op, left, right } => {
                self.eval_node(left)?;
                let left_val = self.return_value.take().ok_or(RuntimeError::EmptyReturn)?;

                self.eval_node(right)?;
                let right_val = self.return_value.take().ok_or(RuntimeError::EmptyReturn)?;

                let result = self.eval_binary_op(op, left_val, right_val)?;
                self.return_value = Some(result);
                Ok(())
            }
            IRNode::UnaryOp { op, operand } => {
                self.eval_node(operand)?;
                let val = self.return_value.take().ok_or(RuntimeError::EmptyReturn)?;
                let result = self.eval_unary_op(op, val)?;
                self.return_value = Some(result);
                Ok(())
            }
            IRNode::If { condition, then_branch, else_branch } => {
                self.eval_node(condition)?;
                let cond_val = self.return_value.take().ok_or(RuntimeError::EmptyReturn)?;

                if cond_val.to_bool() {
                    for node in then_branch {
                        self.eval_node(node)?;
                        if self.return_value.is_some() {
                            break;
                        }
                    }
                } else if let Some(else_nodes) = else_branch {
                    for node in else_nodes {
                        self.eval_node(node)?;
                        if self.return_value.is_some() {
                            break;
                        }
                    }
                } else {
                    self.return_value = Some(Value::None);
                }
                Ok(())
            }
            IRNode::Block { statements } => {
                for node in statements {
                    self.eval_node(node)?;
                }
                Ok(())
            }
            IRNode::Return { value } => {
                if let Some(val) = value {
                    self.eval_node(val)?;
                } else {
                    self.return_value = Some(Value::None);
                }
                Ok(())
            }
            _ => Err(RuntimeError::InvalidOperation(format!("Unsupported node: {:?}", node))),
        }
    }

    /// 이항 연산 평가
    fn eval_binary_op(
        &self,
        op: &str,
        left: Value,
        right: Value,
    ) -> Result<Value, RuntimeError> {
        match op {
            "+" => self.eval_add(left, right),
            "-" => self.eval_subtract(left, right),
            "*" => self.eval_multiply(left, right),
            "/" => self.eval_divide(left, right),
            "%" => self.eval_modulo(left, right),
            "==" => Ok(Value::Boolean(left.equals(&right))),
            "!=" => Ok(Value::Boolean(!left.equals(&right))),
            "<" => self.eval_less_than(left, right),
            "<=" => self.eval_less_equal(left, right),
            ">" => self.eval_greater_than(left, right),
            ">=" => self.eval_greater_equal(left, right),
            "&&" => Ok(Value::Boolean(left.to_bool() && right.to_bool())),
            "||" => Ok(Value::Boolean(left.to_bool() || right.to_bool())),
            _ => Err(RuntimeError::InvalidOperation(format!("Unknown operator: {}", op))),
        }
    }

    /// 단항 연산 평가
    fn eval_unary_op(&self, op: &str, operand: Value) -> Result<Value, RuntimeError> {
        match op {
            "-" => match operand {
                Value::Integer(n) => Ok(Value::Integer(-n)),
                Value::Float(f) => Ok(Value::Float(-f)),
                _ => Err(RuntimeError::TypeMismatch {
                    expected: "numeric".to_string(),
                    got: operand.type_name().to_string(),
                }),
            },
            "!" => Ok(Value::Boolean(!operand.to_bool())),
            _ => Err(RuntimeError::InvalidOperation(format!("Unknown unary operator: {}", op))),
        }
    }

    // 산술 연산
    fn eval_add(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
        match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a + b)),
            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a + b)),
            (Value::Integer(a), Value::Float(b)) => Ok(Value::Float(a as f64 + b)),
            (Value::Float(a), Value::Integer(b)) => Ok(Value::Float(a + b as f64)),
            (Value::String(a), Value::String(b)) => Ok(Value::String(format!("{}{}", a, b))),
            (left, right) => Err(RuntimeError::TypeMismatch {
                expected: "numeric or string".to_string(),
                got: format!("{} + {}", left.type_name(), right.type_name()),
            }),
        }
    }

    fn eval_subtract(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
        match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a - b)),
            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a - b)),
            (Value::Integer(a), Value::Float(b)) => Ok(Value::Float(a as f64 - b)),
            (Value::Float(a), Value::Integer(b)) => Ok(Value::Float(a - b as f64)),
            (left, right) => Err(RuntimeError::TypeMismatch {
                expected: "numeric".to_string(),
                got: format!("{} - {}", left.type_name(), right.type_name()),
            }),
        }
    }

    fn eval_multiply(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
        match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a * b)),
            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a * b)),
            (Value::Integer(a), Value::Float(b)) => Ok(Value::Float(a as f64 * b)),
            (Value::Float(a), Value::Integer(b)) => Ok(Value::Float(a * b as f64)),
            (left, right) => Err(RuntimeError::TypeMismatch {
                expected: "numeric".to_string(),
                got: format!("{} * {}", left.type_name(), right.type_name()),
            }),
        }
    }

    fn eval_divide(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
        match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => {
                if b == 0 {
                    Err(RuntimeError::DivisionByZero)
                } else {
                    Ok(Value::Integer(a / b))
                }
            }
            (Value::Float(a), Value::Float(b)) => {
                if b == 0.0 {
                    Err(RuntimeError::DivisionByZero)
                } else {
                    Ok(Value::Float(a / b))
                }
            }
            (Value::Integer(a), Value::Float(b)) => {
                if b == 0.0 {
                    Err(RuntimeError::DivisionByZero)
                } else {
                    Ok(Value::Float(a as f64 / b))
                }
            }
            (Value::Float(a), Value::Integer(b)) => {
                if b == 0 {
                    Err(RuntimeError::DivisionByZero)
                } else {
                    Ok(Value::Float(a / b as f64))
                }
            }
            (left, right) => Err(RuntimeError::TypeMismatch {
                expected: "numeric".to_string(),
                got: format!("{} / {}", left.type_name(), right.type_name()),
            }),
        }
    }

    fn eval_modulo(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
        match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => {
                if b == 0 {
                    Err(RuntimeError::DivisionByZero)
                } else {
                    Ok(Value::Integer(a % b))
                }
            }
            (left, right) => Err(RuntimeError::TypeMismatch {
                expected: "integer".to_string(),
                got: format!("{} % {}", left.type_name(), right.type_name()),
            }),
        }
    }

    // 비교 연산
    fn eval_less_than(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
        match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Boolean(a < b)),
            (Value::Float(a), Value::Float(b)) => Ok(Value::Boolean(a < b)),
            (Value::Integer(a), Value::Float(b)) => Ok(Value::Boolean((a as f64) < b)),
            (Value::Float(a), Value::Integer(b)) => Ok(Value::Boolean(a < (b as f64))),
            (left, right) => Err(RuntimeError::TypeMismatch {
                expected: "numeric".to_string(),
                got: format!("{} < {}", left.type_name(), right.type_name()),
            }),
        }
    }

    fn eval_less_equal(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
        match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Boolean(a <= b)),
            (Value::Float(a), Value::Float(b)) => Ok(Value::Boolean(a <= b)),
            (Value::Integer(a), Value::Float(b)) => Ok(Value::Boolean((a as f64) <= b)),
            (Value::Float(a), Value::Integer(b)) => Ok(Value::Boolean(a <= (b as f64))),
            (left, right) => Err(RuntimeError::TypeMismatch {
                expected: "numeric".to_string(),
                got: format!("{} <= {}", left.type_name(), right.type_name()),
            }),
        }
    }

    fn eval_greater_than(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
        match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Boolean(a > b)),
            (Value::Float(a), Value::Float(b)) => Ok(Value::Boolean(a > b)),
            (Value::Integer(a), Value::Float(b)) => Ok(Value::Boolean((a as f64) > b)),
            (Value::Float(a), Value::Integer(b)) => Ok(Value::Boolean(a > (b as f64))),
            (left, right) => Err(RuntimeError::TypeMismatch {
                expected: "numeric".to_string(),
                got: format!("{} > {}", left.type_name(), right.type_name()),
            }),
        }
    }

    fn eval_greater_equal(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
        match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Boolean(a >= b)),
            (Value::Float(a), Value::Float(b)) => Ok(Value::Boolean(a >= b)),
            (Value::Integer(a), Value::Float(b)) => Ok(Value::Boolean((a as f64) >= b)),
            (Value::Float(a), Value::Integer(b)) => Ok(Value::Boolean(a >= (b as f64))),
            (left, right) => Err(RuntimeError::TypeMismatch {
                expected: "numeric".to_string(),
                got: format!("{} >= {}", left.type_name(), right.type_name()),
            }),
        }
    }

    pub fn heap(&self) -> &Heap {
        &self.heap
    }

    pub fn stack(&self) -> &Stack {
        &self.stack
    }

    pub fn heap_mut(&mut self) -> &mut Heap {
        &mut self.heap
    }

    pub fn stack_mut(&mut self) -> &mut Stack {
        &mut self.stack
    }
}

