// 문자열 메서드 (String Methods)
// Phase 6 Stage 1

use crate::value::Value;

/// 문자열의 길이를 반환합니다
pub fn length(s: &str) -> i64 {
    s.len() as i64
}

/// 문자열을 대문자로 변환합니다
pub fn uppercase(s: &str) -> String {
    s.to_uppercase()
}

/// 문자열을 소문자로 변환합니다
pub fn lowercase(s: &str) -> String {
    s.to_lowercase()
}

/// 문자열의 앞뒤 공백을 제거합니다
pub fn trim(s: &str) -> String {
    s.trim().to_string()
}

/// 문자열의 앞 공백을 제거합니다
pub fn trim_start(s: &str) -> String {
    s.trim_start().to_string()
}

/// 문자열의 뒤 공백을 제거합니다
pub fn trim_end(s: &str) -> String {
    s.trim_end().to_string()
}

/// 문자열을 구분자로 분할합니다
pub fn split(s: &str, delimiter: &str) -> Vec<Value> {
    s.split(delimiter)
        .map(|part| Value::String(part.to_string()))
        .collect()
}

/// 문자열 배열을 구분자로 결합합니다
pub fn join(parts: &[Value], delimiter: &str) -> Result<String, String> {
    let strings: Result<Vec<String>, String> = parts
        .iter()
        .map(|v| match v {
            Value::String(s) => Ok(s.clone()),
            _ => Err(format!("Cannot join non-string value: {}", v.type_name())),
        })
        .collect();

    strings.map(|strs| strs.join(delimiter))
}

/// 문자열이 부분 문자열을 포함하는지 확인합니다
pub fn contains(s: &str, substr: &str) -> bool {
    s.contains(substr)
}

/// 문자열이 접두사로 시작하는지 확인합니다
pub fn starts_with(s: &str, prefix: &str) -> bool {
    s.starts_with(prefix)
}

/// 문자열이 접미사로 끝나는지 확인합니다
pub fn ends_with(s: &str, suffix: &str) -> bool {
    s.ends_with(suffix)
}

/// 문자열에서 부분 문자열을 다른 문자열로 치환합니다
pub fn replace(s: &str, from: &str, to: &str) -> String {
    s.replace(from, to)
}

/// 문자열에서 모든 부분 문자열을 다른 문자열로 치환합니다
pub fn replace_all(s: &str, from: &str, to: &str) -> String {
    s.replace(from, to)
}

/// 문자열의 부분을 추출합니다
pub fn slice(s: &str, start: i64, end: i64) -> Result<String, String> {
    let len = s.len() as i64;
    let start = if start < 0 { (len + start) as usize } else { start as usize };
    let end = if end < 0 { (len + end) as usize } else { end as usize };

    if start > end || start > s.len() {
        return Err("Invalid slice indices".to_string());
    }

    Ok(s.chars()
        .skip(start)
        .take(end - start)
        .collect::<String>())
}

/// 문자열의 특정 위치의 문자를 반환합니다
pub fn char_at(s: &str, index: i64) -> Result<String, String> {
    if index < 0 {
        return Err("Index out of bounds".to_string());
    }

    s.chars()
        .nth(index as usize)
        .map(|c| c.to_string())
        .ok_or_else(|| "Index out of bounds".to_string())
}

/// 문자열이 반복되는 횟수를 계산합니다
pub fn repeat(s: &str, count: i64) -> Result<String, String> {
    if count < 0 {
        return Err("Count must be non-negative".to_string());
    }

    Ok(s.repeat(count as usize))
}

/// 패턴의 처음 나타나는 위치를 반환합니다
pub fn index_of(s: &str, pattern: &str) -> Option<i64> {
    s.find(pattern).map(|pos| pos as i64)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_length() {
        assert_eq!(length("hello"), 5);
        assert_eq!(length(""), 0);
        assert_eq!(length("한글"), 6); // UTF-8 바이트 길이
    }

    #[test]
    fn test_uppercase() {
        assert_eq!(uppercase("hello"), "HELLO");
        assert_eq!(uppercase("HeLLo"), "HELLO");
    }

    #[test]
    fn test_lowercase() {
        assert_eq!(lowercase("HELLO"), "hello");
        assert_eq!(lowercase("HeLLo"), "hello");
    }

    #[test]
    fn test_trim() {
        assert_eq!(trim("  hello  "), "hello");
        assert_eq!(trim("hello"), "hello");
        assert_eq!(trim("   "), "");
    }

    #[test]
    fn test_trim_start() {
        assert_eq!(trim_start("  hello  "), "hello  ");
    }

    #[test]
    fn test_trim_end() {
        assert_eq!(trim_end("  hello  "), "  hello");
    }

    #[test]
    fn test_split() {
        let result = split("a,b,c", ",");
        assert_eq!(result.len(), 3);
        assert!(matches!(&result[0], Value::String(s) if s == "a"));
    }

    #[test]
    fn test_join() {
        let parts = vec![
            Value::String("a".to_string()),
            Value::String("b".to_string()),
            Value::String("c".to_string()),
        ];
        let result = join(&parts, ",").unwrap();
        assert_eq!(result, "a,b,c");
    }

    #[test]
    fn test_contains() {
        assert!(contains("hello world", "world"));
        assert!(!contains("hello world", "xyz"));
    }

    #[test]
    fn test_starts_with() {
        assert!(starts_with("hello", "he"));
        assert!(!starts_with("hello", "lo"));
    }

    #[test]
    fn test_ends_with() {
        assert!(ends_with("hello", "lo"));
        assert!(!ends_with("hello", "he"));
    }

    #[test]
    fn test_replace() {
        assert_eq!(replace("hello world", "world", "rust"), "hello rust");
        assert_eq!(replace("a a a", "a", "b"), "b b b");
    }

    #[test]
    fn test_char_at() {
        assert_eq!(char_at("hello", 0).unwrap(), "h");
        assert_eq!(char_at("hello", 4).unwrap(), "o");
        assert!(char_at("hello", 10).is_err());
    }

    #[test]
    fn test_repeat() {
        assert_eq!(repeat("ab", 3).unwrap(), "ababab");
        assert_eq!(repeat("x", 1).unwrap(), "x");
        assert_eq!(repeat("y", 0).unwrap(), "");
    }

    #[test]
    fn test_index_of() {
        assert_eq!(index_of("hello", "ll"), Some(2));
        assert_eq!(index_of("hello", "x"), None);
        assert_eq!(index_of("hello", "hello"), Some(0));
    }
}

