}

/// 배열의 모든 요소를 하나의 값으로 축약합니다
pub fn reduce(arr: &[Value], init: Value, reducer: impl Fn(Value, &Value) -> Value) -> Value {
    arr.iter().fold(init, |acc, v| reducer(acc, v))
}

/// 배열에서 특정 요소를 제거합니다
pub fn remove(arr: &[Value], index: i64) -> Result<Vec<Value>, String> {
    if index < 0 || index >= arr.len() as i64 {
        return Err("Index out of bounds".to_string());
    }

    let mut result = arr.to_vec();
    result.remove(index as usize);
    Ok(result)
}

/// 배열의 마지막 요소를 반환합니다
pub fn last(arr: &[Value]) -> Option<Value> {
    arr.last().cloned()
}

