// 수학 함수 (Math Functions)
// Phase 6 Stage 3

use std::f64::consts::PI;

/// 절댓값을 반환합니다
pub fn abs(n: f64) -> f64 {
    n.abs()
}

/// 제곱근을 반환합니다
pub fn sqrt(n: f64) -> f64 {
    n.sqrt()
}

/// 거듭제곱을 반환합니다
pub fn pow(base: f64, exp: f64) -> f64 {
    base.powf(exp)
}

/// 자연 로그를 반환합니다
pub fn ln(n: f64) -> f64 {
    n.ln()
}

/// 로그 10을 반환합니다
pub fn log10(n: f64) -> f64 {
    n.log10()
}

/// 사인 함수 (라디안)
pub fn sin(angle: f64) -> f64 {
    angle.sin()
}

/// 코사인 함수 (라디안)
pub fn cos(angle: f64) -> f64 {
    angle.cos()
}

/// 탄젠트 함수 (라디안)
pub fn tan(angle: f64) -> f64 {
    angle.tan()
}

/// 아크사인 함수
pub fn asin(x: f64) -> f64 {
    x.asin()
}

/// 아크코사인 함수
pub fn acos(x: f64) -> f64 {
    x.acos()
}

/// 아크탄젠트 함수
pub fn atan(x: f64) -> f64 {
    x.atan()
}

/// 내림 (바닥)
pub fn floor(n: f64) -> f64 {
    n.floor()
}

/// 올림 (천장)
pub fn ceil(n: f64) -> f64 {
    n.ceil()
}

/// 반올림
pub fn round(n: f64) -> f64 {
    n.round()
}

/// 소수 부분 제거 (0쪽으로)
pub fn trunc(n: f64) -> f64 {
    n.trunc()
}

/// 최댓값을 반환합니다
pub fn max(a: f64, b: f64) -> f64 {
    if a >= b { a } else { b }
}

/// 최솟값을 반환합니다
pub fn min(a: f64, b: f64) -> f64 {
    if a <= b { a } else { b }
}

/// 두 수의 최댓값 (최대 3개)
pub fn max_3(a: f64, b: f64, c: f64) -> f64 {
    max(max(a, b), c)
}

/// 두 수의 최솟값 (최소 3개)
pub fn min_3(a: f64, b: f64, c: f64) -> f64 {
    min(min(a, b), c)
}

/// 지수 함수 (e^x)
pub fn exp(x: f64) -> f64 {
    x.exp()
}

/// 도를 라디안으로 변환합니다
pub fn degrees_to_radians(degrees: f64) -> f64 {
    degrees * PI / 180.0
}

/// 라디안을 도로 변환합니다
pub fn radians_to_degrees(radians: f64) -> f64 {
    radians * 180.0 / PI
}

/// 두 수의 나머지를 반환합니다
pub fn modulo(a: f64, b: f64) -> f64 {
    a % b
}

/// 부호를 반환합니다 (-1, 0, 1)
pub fn sign(n: f64) -> f64 {
    if n > 0.0 {
        1.0
    } else if n < 0.0 {
        -1.0
    } else {
        0.0
    }
}

/// 범위 제한 (clamp)
pub fn clamp(n: f64, min: f64, max: f64) -> f64 {
    if n < min {
        min
    } else if n > max {
        max
    } else {
        n
    }
}

/// 선형 보간 (Linear Interpolation)
pub fn lerp(a: f64, b: f64, t: f64) -> f64 {
    a + (b - a) * t
}

/// PI 상수
pub fn pi() -> f64 {
    PI
}

/// E (자연 로그의 밑) 상수
pub fn e() -> f64 {
    std::f64::consts::E
}

