mod tests {
    use super::*;

    #[test]
    fn test_abs() {
        assert_eq!(abs(-42.0), 42.0);
        assert_eq!(abs(42.0), 42.0);
        assert_eq!(abs(0.0), 0.0);
    }

    #[test]
    fn test_sqrt() {
        assert_eq!(sqrt(16.0), 4.0);
        assert_eq!(sqrt(25.0), 5.0);
        assert!((sqrt(2.0) - 1.414213562).abs() < 0.001);
    }

    #[test]
    fn test_pow() {
        assert_eq!(pow(2.0, 3.0), 8.0);
        assert_eq!(pow(5.0, 2.0), 25.0);
        assert_eq!(pow(10.0, 0.0), 1.0);
    }

    #[test]
    fn test_floor() {
        assert_eq!(floor(3.7), 3.0);
        assert_eq!(floor(3.2), 3.0);
        assert_eq!(floor(-3.7), -4.0);
    }

    #[test]
    fn test_ceil() {
        assert_eq!(ceil(3.2), 4.0);
        assert_eq!(ceil(3.7), 4.0);
        assert_eq!(ceil(-3.2), -3.0);
    }

    #[test]
    fn test_round() {
        assert_eq!(round(3.4), 3.0);
        assert_eq!(round(3.6), 4.0);
        assert_eq!(round(3.5), 4.0);
    }

    #[test]
    fn test_max() {
        assert_eq!(max(5.0, 3.0), 5.0);
        assert_eq!(max(-5.0, -3.0), -3.0);
        assert_eq!(max(0.0, 0.0), 0.0);
    }

    #[test]
    fn test_min() {
        assert_eq!(min(5.0, 3.0), 3.0);
        assert_eq!(min(-5.0, -3.0), -5.0);
        assert_eq!(min(0.0, 0.0), 0.0);
    }

    #[test]
    fn test_sin() {
        assert!((sin(PI / 2.0) - 1.0).abs() < 0.001);
        assert!((sin(0.0) - 0.0).abs() < 0.001);
    }

    #[test]
    fn test_cos() {
        assert!((cos(0.0) - 1.0).abs() < 0.001);
        assert!((cos(PI) - (-1.0)).abs() < 0.001);
    }

    #[test]
    fn test_tan() {
        assert!((tan(0.0) - 0.0).abs() < 0.001);
    }

    #[test]
    fn test_exp() {
        assert!((exp(0.0) - 1.0).abs() < 0.001);
        assert!(exp(1.0) > 2.7);
    }

    #[test]
    fn test_sign() {
        assert_eq!(sign(5.0), 1.0);
        assert_eq!(sign(-5.0), -1.0);
        assert_eq!(sign(0.0), 0.0);
    }

    #[test]
    fn test_clamp() {
        assert_eq!(clamp(5.0, 0.0, 10.0), 5.0);
        assert_eq!(clamp(-5.0, 0.0, 10.0), 0.0);
        assert_eq!(clamp(15.0, 0.0, 10.0), 10.0);
    }

    #[test]
    fn test_degrees_to_radians() {
        assert!((degrees_to_radians(180.0) - PI).abs() < 0.001);
        assert!((degrees_to_radians(90.0) - PI / 2.0).abs() < 0.001);
    }

    #[test]
    fn test_radians_to_degrees() {
        assert!((radians_to_degrees(PI) - 180.0).abs() < 0.001);
        assert!((radians_to_degrees(PI / 2.0) - 90.0).abs() < 0.001);
    }

    #[test]
    fn test_pi() {
        assert!((pi() - 3.14159265).abs() < 0.001);
    }

    #[test]
    fn test_e() {
        assert!((e() - 2.71828182).abs() < 0.001);
    }
}

