// FV-Lang (Free Value Language)
// A functional-first programming language with strong type inference
//
// This library provides the core compiler infrastructure:
// - Lexer: Tokenization
// - Parser: Abstract Syntax Tree construction
// - Type System: Type inference and checking
// - Code Generator: Compilation to IR/Native code

pub mod lexer;
pub mod parser;
pub mod ast;
pub mod types;
pub mod symbols;
pub mod type_checker;
pub mod ir;
pub mod codegen;
pub mod value;
pub mod heap;
pub mod stack;
pub mod runtime;
pub mod compiler;

pub use lexer::Lexer;
pub use parser::Parser;
pub use ast::Program;
pub use types::Type;
pub use symbols::SymbolTable;
pub use type_checker::{TypeChecker, TypeError};
pub use codegen::CodeGenerator;
pub use value::Value;
pub use heap::Heap;
pub use stack::{Stack, StackFrame};
pub use runtime::{Runtime, RuntimeError};
pub use compiler::{Compiler, CompileError, CompilationResult};

/// Compile FV-Lang source code to executable
pub fn compile(source: &str) -> Result<String, CompileError> {
    // Lexer: Source → Tokens
    let lexer = Lexer::new(source);
    let tokens = lexer.tokenize()?;

    // Parser: Tokens → AST
    let parser = Parser::new(tokens);
    let ast = parser.parse()?;

    // Type Checker: AST → Typed AST
    let type_checker = TypeChecker::new();
    let typed_ast = type_checker.check(&ast)?;

    // Code Generator: Typed AST → IR/Native Code
    let codegen = CodeGenerator::new();
    let code = codegen.generate(&typed_ast)?;

    Ok(code)
}

#[derive(Debug, Clone)]
pub enum CompileError {
    LexerError(String),
    ParserError(String),
    TypeError(String),
    GenerationError(String),
}

impl std::fmt::Display for CompileError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CompileError::LexerError(e) => write!(f, "Lexer error: {}", e),
            CompileError::ParserError(e) => write!(f, "Parser error: {}", e),
            CompileError::TypeError(e) => write!(f, "Type error: {}", e),
            CompileError::GenerationError(e) => write!(f, "Generation error: {}", e),
        }
    }
}

