// 고급 컬렉션 메서드 (Advanced Collections)
// Phase 6 Stage 2: 함수형 프로그래밍

use crate::value::Value;

/// 배열의 모든 요소를 변환합니다 (함수형 맵)
pub fn map_transform(arr: &[Value], transformer: impl Fn(&Value) -> Value) -> Vec<Value> {
    arr.iter().map(|v| transformer(v)).collect()
}

/// 배열에서 조건을 만족하는 요소를 필터링합니다
pub fn filter_items(arr: &[Value], predicate: impl Fn(&Value) -> bool) -> Vec<Value> {
    arr.iter().filter(|v| predicate(v)).collect()
}

/// 배열의 모든 요소를 하나의 값으로 축약합니다 (폴드/리듀스)
pub fn fold_left(arr: &[Value], init: Value, reducer: impl Fn(Value, &Value) -> Value) -> Value {
    arr.iter().fold(init, |acc, v| reducer(acc, v))
}

/// 배열의 모든 요소를 오른쪽에서 왼쪽으로 축약합니다
pub fn fold_right(arr: &[Value], init: Value, reducer: impl Fn(&Value, Value) -> Value) -> Value {
    arr.iter().rev().fold(init, |acc, v| reducer(v, acc))
}

/// 배열의 합계를 계산합니다 (숫자만)
pub fn sum(arr: &[Value]) -> Option<f64> {
    let mut total = 0.0;
    for val in arr {
        match val {
            Value::Integer(n) => total += *n as f64,
            Value::Float(f) => total += f,
            _ => return None,
        }
    }
    Some(total)
}

/// 배열의 평균을 계산합니다
pub fn average(arr: &[Value]) -> Option<f64> {
    if arr.is_empty() {
        return None;
    }
    sum(arr).map(|s| s / arr.len() as f64)
}

/// 배열의 최댓값을 찾습니다
pub fn maximum(arr: &[Value]) -> Option<f64> {
    if arr.is_empty() {
        return None;
    }
    let mut max = std::f64::NEG_INFINITY;
    for val in arr {
        let num = match val {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return None,
        };
        if num > max {
            max = num;
        }
    }
    Some(max)
}

/// 배열의 최솟값을 찾습니다
pub fn minimum(arr: &[Value]) -> Option<f64> {
    if arr.is_empty() {
        return None;
    }
    let mut min = std::f64::INFINITY;
    for val in arr {
        let num = match val {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return None,
        };
        if num < min {
            min = num;
        }
    }
    Some(min)
}

/// 배열을 두 그룹으로 분할합니다
pub fn partition(arr: &[Value], predicate: impl Fn(&Value) -> bool) -> (Vec<Value>, Vec<Value>) {
    let mut true_group = Vec::new();
    let mut false_group = Vec::new();

    for val in arr {
        if predicate(val) {
            true_group.push(val.clone());
        } else {
            false_group.push(val.clone());
        }
    }

    (true_group, false_group)
}

/// 배열의 고유한 요소만 반환합니다
pub fn unique(arr: &[Value]) -> Vec<Value> {
    let mut result = Vec::new();
    for val in arr {
        if !result.iter().any(|v| v.equals(val)) {
            result.push(val.clone());
        }
    }
    result
}

/// 배열을 플래튼합니다 (한 단계)
pub fn flatten_one_level(arr: &[Value]) -> Vec<Value> {
    let mut result = Vec::new();
    for val in arr {
        if let Value::Array(inner) = val {
            result.extend(inner.clone());
        } else {
            result.push(val.clone());
        }
    }
    result
}

/// 두 배열을 병합합니다
pub fn concat(arr1: &[Value], arr2: &[Value]) -> Vec<Value> {
    let mut result = arr1.to_vec();
    result.extend_from_slice(arr2);
    result
}

/// 배열을 지정된 크기의 청크로 분할합니다
pub fn chunk(arr: &[Value], size: usize) -> Vec<Vec<Value>> {
    if size == 0 {
        return vec![];
    }

    let mut result = Vec::new();
    for chunk in arr.chunks(size) {
        result.push(chunk.to_vec());
    }
    result
}

/// 배열의 각 인덱스와 요소를 튜플로 변환합니다
pub fn enumerate(arr: &[Value]) -> Vec<(i64, Value)> {
    arr.iter()
        .enumerate()
        .map(|(i, v)| (i as i64, v.clone()))
        .collect()
}

/// 두 배열을 짝을 이루어 결합합니다
pub fn zip(arr1: &[Value], arr2: &[Value]) -> Vec<(Value, Value)> {
    arr1.iter()
        .zip(arr2.iter())
        .map(|(a, b)| (a.clone(), b.clone()))
        .collect()
}

/// 배열을 조건에 따라 그룹화합니다
pub fn group_by(arr: &[Value], key_fn: impl Fn(&Value) -> String) -> Vec<(String, Vec<Value>)> {
    let mut groups: std::collections::HashMap<String, Vec<Value>> = std::collections::HashMap::new();

    for val in arr {
        let key = key_fn(val);
        groups.entry(key).or_insert_with(Vec::new).push(val.clone());
    }

    let mut result: Vec<_> = groups.into_iter().collect();
    result.sort_by(|a, b| a.0.cmp(&b.0));
    result
}

/// 조건을 만족하는 요소의 개수를 센다
pub fn count_where(arr: &[Value], predicate: impl Fn(&Value) -> bool) -> i64 {
    arr.iter().filter(|v| predicate(v)).count() as i64
}

/// 배열에서 특정 요소의 모든 발생 위치를 찾습니다
pub fn find_all(arr: &[Value], target: &Value) -> Vec<i64> {
    arr.iter()
        .enumerate()
        .filter_map(|(i, v)| {
            if v.equals(target) {
                Some(i as i64)
            } else {
                None
            }
        })
        .collect()
}

