// Phase 6 Stage 2: 배열 & 컬렉션 고차함수 테스트
// Advanced Array & Collection Operations Testing

use fv_lang::stdlib::collections;
use fv_lang::Value;

// ============= 집계 함수 테스트 =============

#[test]
fn test_sum_integers() {
    let arr = vec![Value::Integer(1), Value::Integer(2), Value::Integer(3)];
    assert_eq!(collections::sum(&arr), Some(6.0));
}

#[test]
fn test_sum_floats() {
    let arr = vec![
        Value::Float(1.5),
        Value::Float(2.5),
        Value::Float(1.0),
    ];
    let result = collections::sum(&arr).unwrap();
    assert!((result - 5.0).abs() < 0.001);
}

#[test]
fn test_sum_mixed() {
    let arr = vec![Value::Integer(1), Value::Float(2.5), Value::Integer(3)];
    let result = collections::sum(&arr).unwrap();
    assert!((result - 6.5).abs() < 0.001);
}

#[test]
fn test_average() {
    let arr = vec![Value::Integer(2), Value::Integer(4), Value::Integer(6)];
    assert_eq!(collections::average(&arr), Some(4.0));
}

#[test]
fn test_average_empty_array() {
    let arr: Vec<Value> = vec![];
    assert_eq!(collections::average(&arr), None);
}

#[test]
fn test_maximum() {
    let arr = vec![
        Value::Integer(3),
        Value::Integer(1),
        Value::Integer(4),
        Value::Integer(1),
    ];
    assert_eq!(collections::maximum(&arr), Some(4.0));
}

#[test]
fn test_minimum() {
    let arr = vec![
        Value::Integer(3),
        Value::Integer(1),
        Value::Integer(4),
        Value::Integer(1),
    ];
    assert_eq!(collections::minimum(&arr), Some(1.0));
}

#[test]
fn test_maximum_empty_array() {
    let arr: Vec<Value> = vec![];
    assert_eq!(collections::maximum(&arr), None);
}

// ============= 변환 함수 테스트 =============

#[test]
fn test_unique() {
    let arr = vec![
        Value::Integer(1),
        Value::Integer(2),
        Value::Integer(1),
        Value::Integer(3),
    ];
    let result = collections::unique(&arr);
    assert_eq!(result.len(), 3);
}

#[test]
fn test_unique_all_same() {
    let arr = vec![
        Value::Integer(1),
        Value::Integer(1),
        Value::Integer(1),
    ];
    let result = collections::unique(&arr);
    assert_eq!(result.len(), 1);
}

#[test]
fn test_concat() {
    let arr1 = vec![Value::Integer(1), Value::Integer(2)];
    let arr2 = vec![Value::Integer(3), Value::Integer(4)];
    let result = collections::concat(&arr1, &arr2);
    assert_eq!(result.len(), 4);
    assert!(matches!(&result[0], Value::Integer(1)));
    assert!(matches!(&result[3], Value::Integer(4)));
}

#[test]
fn test_chunk() {
    let arr = vec![
        Value::Integer(1),
        Value::Integer(2),
        Value::Integer(3),
        Value::Integer(4),
        Value::Integer(5),
    ];
    let result = collections::chunk(&arr, 2);
    assert_eq!(result.len(), 3);
    assert_eq!(result[0].len(), 2);
    assert_eq!(result[2].len(), 1);
}

#[test]
fn test_chunk_exact_division() {
    let arr = vec![
        Value::Integer(1),
        Value::Integer(2),
        Value::Integer(3),
        Value::Integer(4),
    ];
    let result = collections::chunk(&arr, 2);
    assert_eq!(result.len(), 2);
    assert_eq!(result[0].len(), 2);
    assert_eq!(result[1].len(), 2);
}

// ============= 파티셔닝 및 그룹화 테스트 =============

#[test]
fn test_partition() {
    let arr = vec![
        Value::Integer(1),
        Value::Integer(2),
        Value::Integer(3),
        Value::Integer(4),
    ];
    let (evens, odds) = collections::partition(&arr, |v| {
        if let Value::Integer(n) = v {
            n % 2 == 0
        } else {
            false
        }
    });
    assert_eq!(evens.len(), 2);
    assert_eq!(odds.len(), 2);
}

#[test]
fn test_count_where() {
    let arr = vec![Value::Integer(1), Value::Integer(2), Value::Integer(3)];
    let count = collections::count_where(&arr, |v| {
        if let Value::Integer(n) = v {
            n % 2 == 0
        } else {
            false
        }
    });
    assert_eq!(count, 1);
}

#[test]
fn test_find_all() {
    let arr = vec![
        Value::Integer(1),
        Value::Integer(2),
        Value::Integer(1),
        Value::Integer(3),
        Value::Integer(1),
    ];
    let positions = collections::find_all(&arr, &Value::Integer(1));
    assert_eq!(positions, vec![0, 2, 4]);
}

#[test]
fn test_find_all_not_found() {
    let arr = vec![
        Value::Integer(1),
        Value::Integer(2),
        Value::Integer(3),
    ];
    let positions = collections::find_all(&arr, &Value::Integer(99));
    assert_eq!(positions.len(), 0);
}

// ============= 유틸리티 테스트 =============

#[test]
fn test_enumerate() {
    let arr = vec![Value::Integer(10), Value::Integer(20)];
    let result = collections::enumerate(&arr);
    assert_eq!(result.len(), 2);
    assert_eq!(result[0].0, 0);
    assert_eq!(result[1].0, 1);
}

#[test]
fn test_zip() {
    let arr1 = vec![Value::Integer(1), Value::Integer(2)];
    let arr2 = vec![Value::Integer(10), Value::Integer(20)];
    let result = collections::zip(&arr1, &arr2);
    assert_eq!(result.len(), 2);
}

#[test]
fn test_zip_different_lengths() {
    let arr1 = vec![Value::Integer(1), Value::Integer(2), Value::Integer(3)];
    let arr2 = vec![Value::Integer(10), Value::Integer(20)];
    let result = collections::zip(&arr1, &arr2);
    assert_eq!(result.len(), 2); // 짧은 쪽에 맞춤
}

#[test]
fn test_flatten_one_level() {
    let arr = vec![
        Value::Array(vec![Value::Integer(1), Value::Integer(2)]),
        Value::Array(vec![Value::Integer(3), Value::Integer(4)]),
    ];
    let result = collections::flatten_one_level(&arr);
    assert_eq!(result.len(), 4);
}

// ============= 함수형 프로그래밍 테스트 =============

#[test]
fn test_fold_left_sum() {
    let arr = vec![Value::Integer(1), Value::Integer(2), Value::Integer(3)];
    let result = collections::fold_left(arr, Value::Integer(0), |acc, v| {
        if let (Value::Integer(a), Value::Integer(b)) = (acc, v) {
            Value::Integer(a + b)
        } else {
            Value::Integer(0)
        }
    });
    assert!(matches!(result, Value::Integer(6)));
}

#[test]
fn test_fold_left_string_concat() {
    let arr = vec![
        Value::String("a".to_string()),
        Value::String("b".to_string()),
        Value::String("c".to_string()),
    ];
    let result = collections::fold_left(arr, Value::String("".to_string()), |acc, v| {
        if let (Value::String(a), Value::String(b)) = (acc, v) {
            Value::String(format!("{}{}", a, b))
        } else {
            Value::String("".to_string())
        }
    });
    assert!(matches!(result, Value::String(ref s) if s == "abc"));
}

#[test]
fn test_map_transform() {
    let arr = vec![Value::Integer(1), Value::Integer(2), Value::Integer(3)];
    let result = collections::map_transform(&arr, |v| {
        if let Value::Integer(n) = v {
            Value::Integer(n * 2)
        } else {
            v.clone()
        }
    });
    assert_eq!(result.len(), 3);
    assert!(matches!(&result[0], Value::Integer(2)));
    assert!(matches!(&result[1], Value::Integer(4)));
    assert!(matches!(&result[2], Value::Integer(6)));
}

#[test]
fn test_filter_items() {
    let arr = vec![
        Value::Integer(1),
        Value::Integer(2),
        Value::Integer(3),
        Value::Integer(4),
    ];
    let result = collections::filter_items(&arr, |v| {
        if let Value::Integer(n) = v {
            n % 2 == 0
        } else {
            false
        }
    });
    assert_eq!(result.len(), 2);
    assert!(matches!(&result[0], Value::Integer(2)));
    assert!(matches!(&result[1], Value::Integer(4)));
}

// ============= 복합 시나리오 테스트 =============

#[test]
fn test_map_then_sum() {
    // [1, 2, 3] -> map(x*2) -> [2, 4, 6] -> sum -> 12
    let arr = vec![Value::Integer(1), Value::Integer(2), Value::Integer(3)];
    let mapped = collections::map_transform(&arr, |v| {
        if let Value::Integer(n) = v {
            Value::Integer(n * 2)
        } else {
            v.clone()
        }
    });
    let sum_result = collections::sum(&mapped).unwrap();
    assert_eq!(sum_result, 12.0);
}

#[test]
