// 고급 함수 (Advanced Functions)
// Phase 6 Stage 3: 통계, 랜덤, 유틸리티

use crate::value::Value;
use std::collections::HashMap;

/// 배열의 분산(Variance)을 계산합니다
pub fn variance(arr: &[Value]) -> Option<f64> {
    if arr.is_empty() {
        return None;
    }

    let mut sum = 0.0;
    let mut count = 0;

    for val in arr {
        let num = match val {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return None,
        };
        sum += num;
        count += 1;
    }

    let mean = sum / count as f64;
    let mut variance_sum = 0.0;

    for val in arr {
        let num = match val {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return None,
        };
        variance_sum += (num - mean).powi(2);
    }

    Some(variance_sum / count as f64)
}

/// 배열의 표준편차(Standard Deviation)를 계산합니다
pub fn standard_deviation(arr: &[Value]) -> Option<f64> {
    variance(arr).map(|v| v.sqrt())
}

/// 배열의 중앙값(Median)을 계산합니다
pub fn median(arr: &[Value]) -> Option<f64> {
    if arr.is_empty() {
        return None;
    }

    let mut nums: Vec<f64> = Vec::new();
    for val in arr {
        let num = match val {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return None,
        };
        nums.push(num);
    }

    nums.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    let mid = nums.len() / 2;
    if nums.len() % 2 == 0 {
        Some((nums[mid - 1] + nums[mid]) / 2.0)
    } else {
        Some(nums[mid])
    }
}

/// 배열의 최빈값(Mode)을 찾습니다
pub fn mode(arr: &[Value]) -> Option<Value> {
    if arr.is_empty() {
        return None;
    }

    let mut freq_map: HashMap<String, i64> = HashMap::new();

    for val in arr {
        let key = val.to_string();
        *freq_map.entry(key).or_insert(0) += 1;
    }

    let (most_freq_key, _) = freq_map
        .iter()
        .max_by_key(|(_, count)| *count)?;

    // 문자열 키를 원래 Value로 복원 시도
    for val in arr {
        if val.to_string() == *most_freq_key {
            return Some(val.clone());
        }
    }

    None
}

/// 범위 내의 랜덤 정수를 생성합니다
pub fn random_integer(min: i64, max: i64) -> i64 {
    use std::time::{SystemTime, UNIX_EPOCH};

    let elapsed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();

    let range = (max - min).abs() + 1;
    let random = (elapsed as i64).abs() % range;

    if max >= min {
        min + random
    } else {
        max + random
    }
}

/// 범위 내의 랜덤 실수를 생성합니다
pub fn random_float(min: f64, max: f64) -> f64 {
    use std::time::{SystemTime, UNIX_EPOCH};

    let elapsed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();

    let random_part = (elapsed as f64 % 1000.0) / 1000.0;
    min + (max - min) * random_part
}

/// 0.0과 1.0 사이의 랜덤 실수를 생성합니다
pub fn random() -> f64 {
    random_float(0.0, 1.0)
}

/// 배열에서 랜덤 요소를 선택합니다
pub fn random_choice(arr: &[Value]) -> Option<Value> {
    if arr.is_empty() {
        return None;
    }

    let index = random_integer(0, arr.len() as i64 - 1) as usize;
    arr.get(index).cloned()
}

/// 배열을 섞습니다 (Fisher-Yates shuffle)
pub fn shuffle(arr: &[Value]) -> Vec<Value> {
    let mut result = arr.to_vec();
    let len = result.len();

    for i in (1..len).rev() {
        let j = random_integer(0, i as i64) as usize;
        result.swap(i, j);
    }

    result
}

/// 배열의 범위(Range)를 계산합니다 (max - min)
pub fn range(arr: &[Value]) -> Option<f64> {
    let min = arr.iter().fold(std::f64::INFINITY, |acc, v| {
        let num = match v {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return acc,
        };
        acc.min(num)
    });

    let max = arr.iter().fold(std::f64::NEG_INFINITY, |acc, v| {
        let num = match v {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return acc,
        };
        acc.max(num)
    });

    if min == std::f64::INFINITY || max == std::f64::NEG_INFINITY {
        None
    } else {
        Some(max - min)
    }
}

/// 배열을 정규화합니다 (0-1 범위)
pub fn normalize(arr: &[Value]) -> Result<Vec<Value>, String> {
    if arr.is_empty() {
        return Ok(vec![]);
    }

    let range_val = range(arr).ok_or("Cannot normalize empty or non-numeric array")?;

    if range_val == 0.0 {
        return Ok(arr.iter().map(|_| Value::Float(0.5)).collect());
    }

    let min_val = arr.iter().fold(std::f64::INFINITY, |acc, v| {
        let num = match v {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return acc,
        };
        acc.min(num)
    });

    let normalized: Vec<Value> = arr
        .iter()
        .map(|v| {
            let num = match v {
                Value::Integer(n) => *n as f64,
                Value::Float(f) => *f,
                _ => 0.0,
            };
            Value::Float((num - min_val) / range_val)
        })
        .collect();

    Ok(normalized)
}

/// 배열을 표준화합니다 (Z-score)
pub fn standardize(arr: &[Value]) -> Result<Vec<Value>, String> {
    if arr.is_empty() {
        return Ok(vec![]);
    }

    let avg = arr.iter().fold(0.0, |acc, v| {
        let num = match v {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return acc,
        };
        acc + num / arr.len() as f64
    });

    let stddev = standard_deviation(arr).ok_or("Cannot standardize non-numeric array")?;

    if stddev == 0.0 {
        return Ok(arr.iter().map(|_| Value::Float(0.0)).collect());
    }

    let standardized: Vec<Value> = arr
        .iter()
        .map(|v| {
            let num = match v {
                Value::Integer(n) => *n as f64,
                Value::Float(f) => *f,
                _ => 0.0,
            };
            Value::Float((num - avg) / stddev)
        })
        .collect();

    Ok(standardized)
}

/// 두 배열의 상관계수(Correlation)를 계산합니다
pub fn correlation(arr1: &[Value], arr2: &[Value]) -> Option<f64> {
    if arr1.is_empty() || arr2.is_empty() || arr1.len() != arr2.len() {
        return None;
    }

    let mean1 = arr1.iter().fold(0.0, |acc, v| {
        let num = match v {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return acc,
        };
        acc + num / arr1.len() as f64
    });

    let mean2 = arr2.iter().fold(0.0, |acc, v| {
        let num = match v {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return acc,
        };
        acc + num / arr2.len() as f64
    });

    let mut cov_sum = 0.0;
    let mut var1_sum = 0.0;
    let mut var2_sum = 0.0;

    for (v1, v2) in arr1.iter().zip(arr2.iter()) {
        let num1 = match v1 {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return None,
        };
        let num2 = match v2 {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return None,
        };

        cov_sum += (num1 - mean1) * (num2 - mean2);
        var1_sum += (num1 - mean1).powi(2);
        var2_sum += (num2 - mean2).powi(2);
    }

    let denominator = (var1_sum * var2_sum).sqrt();

    if denominator == 0.0 {
        None
    } else {
        Some(cov_sum / denominator)
    }
}

/// 백분위수(Percentile)를 계산합니다
pub fn percentile(arr: &[Value], p: f64) -> Option<f64> {
    if arr.is_empty() || p < 0.0 || p > 100.0 {
        return None;
    }

    let mut nums: Vec<f64> = Vec::new();
    for val in arr {
        let num = match val {
            Value::Integer(n) => *n as f64,
            Value::Float(f) => *f,
            _ => return None,
        };
        nums.push(num);
    }

    nums.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    let index = (p / 100.0) * (nums.len() - 1) as f64;
    let lower = index.floor() as usize;
    let upper = index.ceil() as usize;
    let weight = index - lower as f64;

    if upper >= nums.len() {
        Some(nums[lower])
    } else {
        Some(nums[lower] * (1.0 - weight) + nums[upper] * weight)
    }
}

